        "CAP-007"
      ],
      "src_ids": [
        "SRC-0026"
      ]
    },
    {
      "kind": "capability",
      "text": "A documented REST API and webhooks are provided for exchanging data with other line-of-business systems.",
      "evidence_ids": [
        "CAP-006"
      ],
      "src_ids": [
        "SRC-0027"
      ]
    }
  ],
  "gap": "No evidence of support for signing on current desktop and mobile browsers, automated reminders within 72 hours, pre-built templates for the College's twelve most used forms, or an on-premises deployment option."
}
